VALUES ('package', 'kashmir-package-7-day', 'Kashmir Package', 'published', '{"id":"kashmir-package-7-day","title":"Kashmir Package","category":"Images of India","brochure_code":"II10","duration":"","difficulty":null,"region":["India","Kashmir","Srinagar","Gulmarg","Sonamarg","Pahalgam"],"summary":"A Kashmir itinerary combining Srinagar, houseboat stays, Mughal gardens and excursions to mountain destinations.","highlights":["Srinagar houseboat","Gulmarg","Sonamarg","Mughal gardens and Shikara ride","Pahalgam"],"source_page":4,"content_flags":["The brochure prints six days for this package while the card states 7 days / 6 nights. Confirm the missing day."],"itinerary":[{"day":1,"title":"Delhi / Srinagar","description":"On arrival in Srinagar. Meet at airport and transfer to a deluxe house boat for overnight in the house boat.","id":"kashmir-package-7-day-day-1","location":"","activities":[],"meals":"","accommodation":"","images":[],"notes":"","visible":true,"stops":[],"transfers":""},{"day":2,"title":"Srinagar / Gulmarg","description":"Morning half-day city tour of the old part of Srinagar. After noon at leisure, overnight house boat.","id":"kashmir-package-7-day-day-2","location":"","activities":[],"meals":"","accommodation":"","images":[],"notes":"","visible":true,"stops":[],"transfers":""},{"day":3,"title":"Srinagar / Sonmarg","description":"After breakfast, proceed to Sonmarg, the meadow of gold, and enjoy its scenic beauty. Spend the day exploring the local area, with an optional pony ride or trek to the glacier. Return to Srinagar overnight at the house boat.","id":"kashmir-package-7-day-day-3","location":"","activities":[],"meals":"","accommodation":"","images":[],"notes":"","visible":true,"stops":[],"transfers":""},{"day":4,"title":"Mughal Garden & Shikara Tour","description":"After breakfast, visit Shankaracharya hill for a bird''s-eye view of Srinagar. Visit the Mughal gardens, Nishat and Shalimar. After lunch, a shikara ride. Overnight in the house boat.",