VALUES ('package', 'south-india-highlight', 'South India Highlight', 'published', '{"id":"south-india-highlight","title":"South India Highlight","category":"India Tours","brochure_code":"IT16","duration":"13 nights / 14 days","difficulty":null,"region":["India","Kerala","Tamil Nadu","Kochi","Munnar","Thekkady","Alleppey","Varkala","Kovalam","Kanyakumari","Rameshwaram","Madurai"],"summary":"A South India circuit through Kerala''s hill stations, wildlife and backwaters, continuing to coastal and temple destinations in Tamil Nadu.","highlights":["Kochi and Fort Kochi","Munnar and Thekkady","Alleppey houseboat","Varkala and Kovalam","Kanyakumari and Rameshwaram","Madurai departure"],"source_page":5,"content_flags":["Package-specific accommodation, meals and exclusions are not fully clear in the brochure. Do not assume the generic panel applies without confirmation."],"itinerary":[{"day":1,"title":"Kochi","description":"Arrival at Cochin Airport. Meet the representative and proceed for local sightseeing covering Mattancherry Palace, Fort Kochi and Chinese Fishing Nets. Overnight stay in Kochi.","id":"south-india-highlight-day-1","location":"","activities":[],"meals":"","accommodation":"","images":[],"notes":"","visible":true,"stops":[],"transfers":""},{"day":2,"title":"Kochi – Munnar","description":"Visit Athirapally Waterfalls, Cardamom Plantation, Spice Garden and Flower Garden.","id":"south-india-highlight-day-2","location":"","activities":[],"meals":"","accommodation":"","images":[],"notes":"","visible":true,"stops":[],"transfers":""},{"day":3,"title":"Munnar","description":"Local sightseeing: Eravikulam National Park, Tea Museum, Mattupetty Dam and Kundala Lake, Echo Point and Photo Point.","id":"south-india-highlight-day-3","location":"","activities":[],"meals":"","accommodation":"","images":[],"notes":"","visible":true,"stops":[],"transfers":""},{"day":4,"title":"Munnar – Thekkady","description":"Visit Periyar Wildlife Sanctuary, Elephant Junction and Kalaripayattu Show.","id":"south-india-highlight-day-4","location":"","activities":[],"meals":"","accommodation":"","images":[],"notes":"","visible":true,"stops":[],"transfers":""},{"day":5,"title":"Thekkady – Alleppey","description":"After breakfast, proceed to Alleppey and board the houseboat by 12:00 noon. Enjoy cruising through the backwaters. Lunch at 13:30 hrs, cruise resumes at 14:30 hrs, with tea and snacks onboard. Houseboat reaches the halt by 18:00 hrs. Overnight stay on the houseboat.","id":"south-india-highlight-day-5","location":"","activities":[],"meals":"","accommodation":"","images":[],"notes":"","visible":true,"stops":[],"transfers":""},{"day":6,"title":"Alleppey","description":"Alleppey Beach, Marari Beach, Alleppey Lighthouse and Alleppey Market.","id":"south-india-highlight-day-6","location":"","activities":[],"meals":"","accommodation":"","images":[],"notes":"","visible":true,"stops":[],"transfers":""},{"day":7,"title":"Alleppey – Varkala","description":"Visit Jatayu Earth Centre and Munroe Island.","id":"south-india-highlight-day-7","location":"","activities":[],"meals":"","accommodation":"","images":[],"notes":"","visible":true,"stops":[],"transfers":""},{"day":8,"title":"Varkala","description":"Local sightseeing: Varkala Beach, Kappil Beach, Varkala Cliff and Sree Janardhan Swamy Temple.","id":"south-india-highlight-day-8","location":"","activities":[],"meals":"","accommodation":"","images":[],"notes":"","visible":true,"stops":[],"transfers":""},{"day":9,"title":"Varkala – Kovalam","description":"Visit Hawah Beach, Samudra Beach, Kovalam Beach and Vizhinjam Lighthouse.","id":"south-india-highlight-day-9","location":"","activities":[],"meals":"","accommodation":"","images":[],"notes":"","visible":true,"stops":[],"transfers":""},{"day":10,"title":"Trivandrum","description":"Local sightseeing: Sree Padmanabha Swamy Temple, Azhimala Shiva Statue, Napier Museum, Sree Chithra Art Gallery and Trivandrum Zoo.","id":"south-india-highlight-day-10","location":"","